<?php require 'config.php';$u=need('admin');
if($_POST&&in_array($_POST['a']??'',['policy','interrupt','bus','complaint'])){chk();$a=$_POST['a'];
 if($a=='policy'){foreach(['student_pct','cancel_fee_pct'] as $k)q('REPLACE INTO settings VALUES(?,?)',[$k,max(0,min(100,(int)$_POST[$k]))]);}
 if($a=='bus'&&in_array($_POST['v'],['approved','rejected','suspended']))q('UPDATE buses SET status=? WHERE id=?',[$_POST['v'],(int)$_POST['id']]);
 if($a=='complaint')q("UPDATE complaints SET status='resolved' WHERE id=?",[(int)$_POST['id']]);
 if($a=='interrupt'){$id=(int)$_POST['id'];$p=max(0,min(100,(int)$_POST['pct']));q("UPDATE trips SET status='interrupted' WHERE id=?",[$id]);
  foreach(q("SELECT * FROM bookings WHERE trip_id=? AND status='confirmed' AND user_id IS NOT NULL",[$id])->fetchAll() as $b){$rf=round($b['fare']*$p/100,2);q('UPDATE bookings SET refund=? WHERE id=?',[$rf,$b['id']]);
   if($b['pay_method']=='card')card_refund($b,$rf);
   notify($b['user_id'],"Your trip was interrupted. Compensation of ৳$rf ($p%) ".($b['pay_method']=='card'?'was added to your card.':'is pending.'));}}
 flash('Saved.');header('Location: admin.php');exit;}
if($_POST){chk();$a=$_POST['a'];$id=(int)$_POST['id'];$v=$_POST['v'];
 if($a=='student'&&in_array($v,['verified','none'])){q('UPDATE users SET student_status=? WHERE id=?',[$v,$id]);notify($id,$v=='verified'?'Your student ID is verified. You now get '.setting('student_pct',50).'% off local bus fares.':'Your student ID was not approved. Please check your details and submit again.');}
 if($a=='report'&&in_array($v,['verified','resolved','rejected']))q('UPDATE reports SET status=? WHERE id=?',[$v,$id]);
 if($a=='trip'&&in_array($v,['scheduled','running','delayed','completed','cancelled'])){q('UPDATE trips SET status=? WHERE id=?',[$v,$id]);
  if($v=='cancelled'){foreach(q("SELECT * FROM bookings WHERE trip_id=? AND status='confirmed'",[$id])->fetchAll() as $b){q("UPDATE bookings SET status='cancelled',active=NULL,refund=fare WHERE id=?",[$b['id']]);notify($b['user_id'],'Your trip was cancelled. Full refund issued.');
   if($b['pay_method']=='card')card_refund($b,$b['fare']);}}}
 q('INSERT INTO audit_logs(user_id,action) VALUES(?,?)',[$u['id'],"$a #$id → $v"]);flash('Updated.');header('Location: admin.php');exit;}
$s=q("SELECT COUNT(*) n,COALESCE(SUM(IF(status='confirmed',fare,0)),0) rev,COALESCE(SUM(refund),0) ref FROM bookings")->fetch();
function sel($a,$id,$opts){echo '<form method="post">'.tok()."<input type=hidden name=a value=$a><input type=hidden name=id value=$id>";foreach($opts as $o)echo "<button class='btn sm ghost' name=v value=$o>$o</button> ";echo '</form>';}
head('Admin');?><h2>Administrator dashboard</h2>
<div class="grid"><div class="card"><div class="big"><?=$s['n']?></div>Bookings</div><div class="card"><div class="big">৳<?=number_format($s['rev'])?></div>Revenue</div><div class="card"><div class="big">৳<?=number_format($s['ref'])?></div>Refunds</div></div>
<h3 style="margin-top:28px">Student verification</h3><?php foreach(q("SELECT * FROM users WHERE student_status='pending'")->fetchAll() as $r){echo '<div class="card trip"><span>'.e($r['name']).' · '.e($r['student_id']).' · session '.e($r['student_session']).' · valid until '.e($r['student_expiry']).' · '.e($r['student_check']).' · <a href="doc.php?f='.e($r['student_front']).'">front</a> <a href="doc.php?f='.e($r['student_back']).'">back</a></span>';sel('student',$r['id'],['verified','none']);echo '</div>';}?>
<h3>Verified students</h3><?php foreach(q("SELECT * FROM users WHERE student_status='verified' ORDER BY id DESC LIMIT 10")->fetchAll() as $r){echo '<div class="card trip"><span>'.e($r['name']).' · '.e($r['student_id']).' · valid until '.e($r['student_expiry']).' · <a href="doc.php?f='.e($r['student_front']).'">front</a> <a href="doc.php?f='.e($r['student_back']).'">back</a></span>';sel('student',$r['id'],['none']);echo '</div>';}?>
<h3>Reports to review</h3><?php foreach(q("SELECT * FROM reports ORDER BY id DESC LIMIT 10")->fetchAll() as $r){echo '<div class="card trip"><span>'.e($r['category']).' · '.e($r['location']).' <span class="pill '.$r['status'].'">'.$r['status'].'</span></span>';sel('report',$r['id'],['verified','resolved','rejected']);echo '</div>';}?>
<h3>Trips</h3><?php foreach(q("SELECT t.*,r.from_city,r.to_city FROM trips t JOIN routes r ON r.id=t.route_id ORDER BY depart_date")->fetchAll() as $r){echo '<div class="card trip"><span>'.e($r['from_city']).' to '.e($r['to_city']).' · '.e($r['depart_date']).' <span class="pill '.$r['status'].'">'.$r['status'].'</span></span>';sel('trip',$r['id'],['running','delayed','completed','cancelled']);echo '</div>';}?>
<h3>Policies</h3><form method="post" class="card row"><?=tok()?><input type="hidden" name="a" value="policy"><label>Student discount % (local buses only)<input type="number" name="student_pct" min="0" max="100" value="<?=setting('student_pct',50)?>"></label><label>Cancellation fee %<input type="number" name="cancel_fee_pct" min="0" max="100" value="<?=setting('cancel_fee_pct',10)?>"></label><button class="btn">Save policies</button></form>
<h3>Bus registrations</h3><?php foreach(q('SELECT * FROM buses ORDER BY id DESC')->fetchAll() as $r){echo '<div class="card trip"><span>'.e($r['reg_number']).' · '.e($r['operator']).' <span class="pill '.($r['status']=='approved'?'verified':'pending').'">'.$r['status'].'</span>'.($r['license_doc']?' <a href="doc.php?f='.e($r['license_doc']).'">licence copy</a>':'').'</span><form method="post">'.tok().'<input type="hidden" name="a" value="bus"><input type="hidden" name="id" value="'.$r['id'].'"><button class="btn sm ghost" name="v" value="approved">approve</button> <button class="btn sm ghost" name="v" value="suspended">suspend</button> <button class="btn sm ghost" name="v" value="rejected">reject</button></form></div>';}?>
<h3>Open complaints</h3><?php foreach(q("SELECT c.*,u.name,u.role FROM complaints c JOIN users u ON u.id=c.user_id WHERE c.status='open'")->fetchAll() as $r){echo '<div class="card trip"><span><strong>'.e($r['subject']).'</strong> by '.e($r['name']).' ('.e($r['role']).')<br>'.e($r['message']).'</span><form method="post">'.tok().'<input type="hidden" name="a" value="complaint"><input type="hidden" name="id" value="'.$r['id'].'"><button class="btn sm ghost">Mark resolved</button></form></div>';}?>
<h3>Interrupted journey compensation</h3><form method="post" class="card row"><?=tok()?><input type="hidden" name="a" value="interrupt"><label>Trip<select name="id"><?php foreach(q("SELECT t.id,t.depart_date,r.from_city,r.to_city FROM trips t JOIN routes r ON r.id=t.route_id WHERE t.status IN('running','delayed')")->fetchAll() as $r)echo '<option value="'.$r['id'].'">'.e($r['from_city'].' to '.$r['to_city'].' · '.$r['depart_date']).'</option>';?></select></label><label>Compensation % of fare<input type="number" name="pct" min="0" max="100" value="50"></label><button class="btn">Apply compensation</button></form>
<h3>SOS requests</h3><div class="scroll"><table><tr><th>Time</th><th>Location</th><th>Note</th></tr><?php foreach(q('SELECT s.*,u.name,u.emergency_contact ec FROM sos s JOIN users u ON u.id=s.user_id ORDER BY s.id DESC LIMIT 10')->fetchAll() as $r)echo '<tr><td>'.e($r['created_at']).'</td><td>'.e($r['name']).' · '.e($r['location']).' · '.e($r['ec']).'</td><td>'.e($r['note']).'</td></tr>';?></table></div><?php foot();
